import React, { useEffect, useState } from "react";
import toast from "react-hot-toast";

import { getAllBookings, getBookingAnalytics, reviewBooking } from "../../api/bookingApi";
import { useAuth } from "../../context/AuthContext.jsx";
import { BOOKING_STATUSES, REVIEWABLE_STATUSES } from "../../utils/constants";

function statusBadge(status) {
  const styles = {
    PENDING: "bg-amber-100 text-amber-800",
    APPROVED: "bg-emerald-100 text-emerald-800",
    REJECTED: "bg-rose-100 text-rose-800",
    CANCELLED: "bg-slate-200 text-slate-700"
  };

  return styles[status] || "bg-slate-100 text-slate-700";
}

function BookingApproval() {
  const { currentUser } = useAuth();
  const [filters, setFilters] = useState({
    status: "",
    resourceId: "",
    requesterId: "",
    bookingDate: ""
  });
  const [reviewState, setReviewState] = useState({});
  const [bookings, setBookings] = useState([]);
  const [analytics, setAnalytics] = useState(null);
  const [loading, setLoading] = useState(true);

  const loadBookings = async (activeFilters = filters) => {
    setLoading(true);
    try {
      const cleanedFilters = Object.fromEntries(
        Object.entries(activeFilters).filter(([, value]) => value !== "")
      );
      const [bookingData, analyticsData] = await Promise.all([
        getAllBookings(cleanedFilters),
        getBookingAnalytics(currentUser.id)
      ]);
      setBookings(bookingData);
      setAnalytics(analyticsData);
    } catch (error) {
      toast.error(error?.response?.data?.message || "Unable to load booking queue");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    const initialFilters = {
      status: "",
      resourceId: "",
      requesterId: "",
      bookingDate: ""
    };

    const fetchInitialData = async () => {
      setLoading(true);
      try {
        const [bookingData, analyticsData] = await Promise.all([
          getAllBookings(),
          getBookingAnalytics(currentUser.id)
        ]);
        setBookings(bookingData);
        setAnalytics(analyticsData);
        setFilters(initialFilters);
      } catch (error) {
        toast.error(error?.response?.data?.message || "Unable to load booking queue");
      } finally {
        setLoading(false);
      }
    };

    fetchInitialData();
  }, [currentUser.id]);

  const handleFilterChange = (event) => {
    const { name, value } = event.target;
    setFilters((previous) => ({ ...previous, [name]: value }));
  };

  const handleReviewChange = (bookingId, field, value) => {
    setReviewState((previous) => ({
      ...previous,
      [bookingId]: {
        status: previous[bookingId]?.status || "APPROVED",
        reason: previous[bookingId]?.reason || "",
        [field]: value
      }
    }));
  };

  const handleApplyFilters = (event) => {
    event.preventDefault();
    loadBookings(filters);
  };

  const handleReview = async (bookingId) => {
    const entry = reviewState[bookingId] || { status: "APPROVED", reason: "" };

    try {
      await reviewBooking(bookingId, {
        adminId: currentUser.id,
        status: entry.status,
        reason: entry.reason
      });
      toast.success(`Booking #${bookingId} ${entry.status.toLowerCase()}`);
      loadBookings();
    } catch (error) {
      toast.error(error?.response?.data?.message || "Unable to review booking");
    }
  };

  const approvedBookings = bookings.filter((booking) => booking.status === "APPROVED");
  const analyticsCards = analytics
    ? [
        { label: "Total bookings", value: analytics.totalBookings, tone: "text-slate-900" },
        { label: "Pending review", value: analytics.pendingBookings, tone: "text-amber-700" },
        { label: "Approved", value: analytics.approvedBookings, tone: "text-emerald-700" },
        { label: "Approval rate", value: `${analytics.approvalRate.toFixed(1)}%`, tone: "text-sky-700" }
      ]
    : [];

  return (
    <div className="space-y-6">
      <section className="rounded-[32px] bg-white p-8 shadow-panel">
        <p className="text-sm font-semibold uppercase tracking-[0.2em] text-teal-700">
          Admin Booking Workflow
        </p>
        <h1 className="mt-3 font-display text-3xl font-semibold text-ink">Review and manage bookings</h1>
        <p className="mt-3 max-w-3xl text-sm leading-6 text-slate-500">
          View all bookings, keep approved requests visible after review, inspect full booking
          details, and manage pending decisions with an admin reason.
        </p>

        <form onSubmit={handleApplyFilters} className="mt-8 grid gap-4 lg:grid-cols-5">
          <select
            name="status"
            value={filters.status}
            onChange={handleFilterChange}
            className="rounded-2xl border border-slate-200 bg-slate-50 px-4 py-3 text-sm outline-none focus:border-teal-400 focus:bg-white"
          >
            <option value="">All statuses</option>
            {BOOKING_STATUSES.map((status) => (
              <option key={status} value={status}>
                {status}
              </option>
            ))}
          </select>

          <input
            type="number"
            name="resourceId"
            placeholder="Resource ID"
            value={filters.resourceId}
            onChange={handleFilterChange}
            className="rounded-2xl border border-slate-200 bg-slate-50 px-4 py-3 text-sm outline-none focus:border-teal-400 focus:bg-white"
          />

          <input
            type="number"
            name="requesterId"
            placeholder="Requester ID"
            value={filters.requesterId}
            onChange={handleFilterChange}
            className="rounded-2xl border border-slate-200 bg-slate-50 px-4 py-3 text-sm outline-none focus:border-teal-400 focus:bg-white"
          />

          <input
            type="date"
            name="bookingDate"
            value={filters.bookingDate}
            onChange={handleFilterChange}
            className="rounded-2xl border border-slate-200 bg-slate-50 px-4 py-3 text-sm outline-none focus:border-teal-400 focus:bg-white"
          />

          <button
            type="submit"
            className="rounded-full bg-teal-700 px-5 py-3 text-sm font-semibold text-white transition hover:bg-teal-800"
          >
            Apply Filters
          </button>
        </form>
      </section>

      <section className="grid gap-5 xl:grid-cols-[1.15fr_0.85fr]">
        <div className="rounded-[32px] bg-white p-7 shadow-panel">
          <div className="flex items-start justify-between gap-4">
            <div>
              <p className="text-sm font-semibold uppercase tracking-[0.2em] text-sky-700">
                Booking Analytics
              </p>
              <h2 className="mt-3 font-display text-2xl font-semibold text-ink">
                Admin booking insights
              </h2>
            </div>
            <button
              type="button"
              onClick={() => loadBookings(filters)}
              className="rounded-full border border-slate-300 px-4 py-2 text-sm font-semibold text-slate-700 transition hover:bg-slate-50"
            >
              Refresh Data
            </button>
          </div>

          <div className="mt-6 grid gap-4 sm:grid-cols-2 xl:grid-cols-4">
            {loading && !analytics ? (
              <div className="col-span-full rounded-3xl bg-slate-50 px-5 py-8 text-center text-sm text-slate-500">
                Loading analytics...
              </div>
            ) : (
              analyticsCards.map((card) => (
                <article key={card.label} className="rounded-[24px] bg-slate-50 p-5">
                  <p className="text-sm text-slate-500">{card.label}</p>
                  <p className={`mt-3 text-3xl font-semibold ${card.tone}`}>{card.value}</p>
                </article>
              ))
            )}
          </div>

          <div className="mt-6 grid gap-4 md:grid-cols-3">
            <div className="rounded-[24px] border border-slate-200 p-5">
              <p className="text-sm text-slate-500">Today&apos;s bookings</p>
              <p className="mt-3 text-2xl font-semibold text-ink">
                {analytics?.todaysBookings ?? 0}
              </p>
            </div>
            <div className="rounded-[24px] border border-slate-200 p-5">
              <p className="text-sm text-slate-500">Upcoming approved</p>
              <p className="mt-3 text-2xl font-semibold text-emerald-700">
                {analytics?.upcomingApprovedBookings ?? 0}
              </p>
            </div>
            <div className="rounded-[24px] border border-slate-200 p-5">
              <p className="text-sm text-slate-500">Declined or cancelled</p>
              <p className="mt-3 text-2xl font-semibold text-rose-700">
                {(analytics?.rejectedBookings ?? 0) + (analytics?.cancelledBookings ?? 0)}
              </p>
            </div>
          </div>
        </div>

        <div className="rounded-[32px] bg-white p-7 shadow-panel">
          <p className="text-sm font-semibold uppercase tracking-[0.2em] text-orange-600">
            Popular Resources
          </p>
          <h2 className="mt-3 font-display text-2xl font-semibold text-ink">
            Most requested spaces
          </h2>

          <div className="mt-6 space-y-4">
            {analytics?.topResources?.length ? (
              analytics.topResources.map((resource) => (
                <article
                  key={resource.resourceId}
                  className="rounded-[24px] bg-slate-50 px-5 py-4"
                >
                  <div className="flex items-center justify-between gap-4">
                    <div>
                      <p className="font-semibold text-ink">{resource.resourceName}</p>
                      <p className="mt-1 text-sm text-slate-500">Resource #{resource.resourceId}</p>
                    </div>
                    <div className="text-right text-sm">
                      <p className="font-semibold text-slate-900">{resource.totalBookings} total</p>
                      <p className="mt-1 text-emerald-700">{resource.approvedBookings} approved</p>
                    </div>
                  </div>
                </article>
              ))
            ) : (
              <div className="rounded-[24px] bg-slate-50 px-5 py-8 text-center text-sm text-slate-500">
                No booking analytics available yet.
              </div>
            )}
          </div>
        </div>
      </section>

      <section className="rounded-[32px] bg-white p-7 shadow-panel">
        <div className="flex flex-col gap-3 sm:flex-row sm:items-end sm:justify-between">
          <div>
            <p className="text-sm font-semibold uppercase tracking-[0.2em] text-emerald-700">
              Approved Bookings
            </p>
            <h2 className="mt-2 font-display text-2xl font-semibold text-ink">
              Approved booking details
            </h2>
          </div>
          <p className="text-sm text-slate-500">
            {approvedBookings.length} approved booking{approvedBookings.length === 1 ? "" : "s"} in the current result.
          </p>
        </div>

        <div className="mt-6 grid gap-4">
          {loading ? (
            <div className="rounded-[24px] bg-slate-50 px-5 py-8 text-center text-sm text-slate-500">
              Loading approved bookings...
            </div>
          ) : approvedBookings.length === 0 ? (
            <div className="rounded-[24px] bg-slate-50 px-5 py-8 text-center text-sm text-slate-500">
              No approved bookings match the current filters.
            </div>
          ) : (
            approvedBookings.map((booking) => (
              <article key={booking.id} className="rounded-[24px] border border-emerald-200 bg-emerald-50/60 p-5">
                <div className="flex flex-wrap items-center gap-3">
                  <span className="rounded-full bg-emerald-600 px-3 py-1 text-xs font-semibold text-white">
                    Approved
                  </span>
                  <span className="rounded-full bg-white px-3 py-1 text-xs font-semibold text-slate-700">
                    Booking #{booking.id}
                  </span>
                  <span className="text-xs font-medium uppercase tracking-wide text-slate-500">
                    Reviewed by {booking.reviewedByName || "Admin"}
                  </span>
                </div>

                <div className="mt-4 grid gap-4 lg:grid-cols-[1.15fr_0.85fr]">
                  <div>
                    <h3 className="font-display text-xl font-semibold text-ink">{booking.resourceName}</h3>
                    <p className="mt-1 text-sm text-slate-500">
                      {booking.resourceLocation} · {booking.resourceType}
                    </p>
                    <p className="mt-4 rounded-3xl bg-white px-4 py-4 text-sm leading-6 text-slate-600">
                      <span className="font-semibold text-ink">Purpose:</span> {booking.purpose}
                    </p>
                  </div>

                  <div className="grid gap-3 text-sm text-slate-600">
                    <p><span className="font-semibold text-ink">Requester:</span> {booking.requesterName}</p>
                    <p><span className="font-semibold text-ink">Email:</span> {booking.requesterEmail}</p>
                    <p><span className="font-semibold text-ink">Date:</span> {booking.bookingDate}</p>
                    <p><span className="font-semibold text-ink">Time:</span> {booking.startTime} - {booking.endTime}</p>
                    <p><span className="font-semibold text-ink">Attendees:</span> {booking.expectedAttendees}</p>
                    <p><span className="font-semibold text-ink">Admin note:</span> {booking.adminReason || "Approved without a note"}</p>
                  </div>
                </div>
              </article>
            ))
          )}
        </div>
      </section>

      <section className="grid gap-5">
        {loading ? (
          <div className="rounded-[32px] bg-white p-10 text-center text-sm text-slate-500 shadow-panel">
            Loading booking queue...
          </div>
        ) : bookings.length === 0 ? (
          <div className="rounded-[32px] bg-white p-10 text-center text-sm text-slate-500 shadow-panel">
            No bookings match the current filters.
          </div>
        ) : (
          bookings.map((booking) => {
            const reviewEntry = reviewState[booking.id] || { status: "APPROVED", reason: "" };

            return (
              <article
                key={booking.id}
                className="rounded-[32px] bg-white p-7 shadow-panel"
              >
                <div className="grid gap-6 lg:grid-cols-[1.2fr_0.9fr]">
                  <div className="space-y-4">
                    <div className="flex flex-wrap items-center gap-3">
                      <span className="rounded-full bg-slate-900 px-3 py-1 text-xs font-semibold text-white">
                        Booking #{booking.id}
                      </span>
                      <span className={`rounded-full px-3 py-1 text-xs font-semibold ${statusBadge(booking.status)}`}>
                        {booking.status}
                      </span>
                    </div>

                    <div>
                      <h2 className="font-display text-2xl font-semibold text-ink">
                        {booking.resourceName}
                      </h2>
                      <p className="mt-1 text-sm text-slate-500">
                        {booking.resourceLocation} · {booking.resourceType}
                      </p>
                    </div>

                    <div className="grid gap-4 sm:grid-cols-2 text-sm text-slate-600">
                      <p>
                        <span className="font-semibold text-ink">Requester:</span> {booking.requesterName}
                      </p>
                      <p>
                        <span className="font-semibold text-ink">Email:</span> {booking.requesterEmail}
                      </p>
                      <p>
                        <span className="font-semibold text-ink">Date:</span> {booking.bookingDate}
                      </p>
                      <p>
                        <span className="font-semibold text-ink">Time:</span> {booking.startTime} - {booking.endTime}
                      </p>
                      <p>
                        <span className="font-semibold text-ink">Attendees:</span> {booking.expectedAttendees}
                      </p>
                      <p>
                        <span className="font-semibold text-ink">Current reason:</span> {booking.adminReason || "N/A"}
                      </p>
                      <p>
                        <span className="font-semibold text-ink">Reviewed by:</span> {booking.reviewedByName || "Not reviewed"}
                      </p>
                      <p>
                        <span className="font-semibold text-ink">Created:</span> {booking.createdAt?.replace("T", " ") || "N/A"}
                      </p>
                    </div>

                    <p className="rounded-3xl bg-slate-50 px-4 py-4 text-sm leading-6 text-slate-600">
                      <span className="font-semibold text-ink">Purpose:</span> {booking.purpose}
                    </p>
                  </div>

                  <div className="rounded-[28px] bg-slate-50 p-5">
                    <h3 className="font-display text-xl font-semibold text-ink">Admin action</h3>
                    <p className="mt-2 text-sm text-slate-500">
                      Only pending bookings can be reviewed by the backend.
                    </p>

                    <div className="mt-6 space-y-4">
                      <select
                        value={reviewEntry.status}
                        onChange={(event) =>
                          handleReviewChange(booking.id, "status", event.target.value)
                        }
                        disabled={booking.status !== "PENDING"}
                        className="w-full rounded-2xl border border-slate-200 bg-white px-4 py-3 text-sm outline-none focus:border-teal-400"
                      >
                        {REVIEWABLE_STATUSES.map((status) => (
                          <option key={status} value={status}>
                            {status}
                          </option>
                        ))}
                      </select>

                      <textarea
                        rows="4"
                        placeholder="Add an admin reason"
                        value={reviewEntry.reason}
                        onChange={(event) =>
                          handleReviewChange(booking.id, "reason", event.target.value)
                        }
                        disabled={booking.status !== "PENDING"}
                        className="w-full rounded-3xl border border-slate-200 bg-white px-4 py-3 text-sm outline-none focus:border-teal-400"
                      />

                      {booking.status === "PENDING" ? (
                        <button
                          type="button"
                          onClick={() => handleReview(booking.id)}
                          className="w-full rounded-full bg-slate-900 px-5 py-3 text-sm font-semibold text-white transition hover:bg-slate-700"
                        >
                          Submit Review
                        </button>
                      ) : (
                        <div className="rounded-3xl border border-slate-200 bg-white px-4 py-4 text-sm text-slate-500">
                          This booking has already been reviewed. Its details remain visible here for admin tracking.
                        </div>
                      )}
                    </div>
                  </div>
                </div>
              </article>
            );
          })
        )}
      </section>
    </div>
  );
}

export default BookingApproval;
